#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

#define BUF_SIZE 0x800

static char main_line[BUF_SIZE];
static char main_key[BUF_SIZE];
static char main_val[BUF_SIZE];

static void decode(const char *src, size_t len, char *dst)
{
    size_t i = 0, o = 0;
    while (i < len) {
        char c = src[i];
        if (c == '+') {
            dst[o++] = ' ';
            ++i;
        } else if (c == '%' && i + 2 < len && isxdigit((unsigned char)src[i+1]) && isxdigit((unsigned char)src[i+2])) {
            char hi = src[i+1];
            char lo = src[i+2];
            int vhi = (hi >= '0' && hi <= '9') ? hi - '0'
                     : (hi >= 'a' && hi <= 'f') ? hi - 'a' + 10
                     : hi - 'A' + 10;
            int vlo = (lo >= '0' && lo <= '9') ? lo - '0'
                     : (lo >= 'a' && lo <= 'f') ? lo - 'a' + 10
                     : lo - 'A' + 10;
            dst[o++] = (char)((vhi << 4) | vlo);
            i += 3;
        } else {
            dst[o++] = c;
            ++i;
        }
    }
    dst[o] = '\0';
}

int main(void)
{
    if (fgets(main_line, sizeof(main_line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    size_t line_len = strlen(main_line);
    while (line_len && (main_line[line_len-1] == '\n' || main_line[line_len-1] == '\r')) {
        main_line[--line_len] = '\0';
    }

    char *p = main_line;
    while (*p) {
        char *key_start = p;
        char *eq = strchr(p, '=');
        char *amp = strchr(p, '&');
        if (!amp) amp = p + strlen(p);

        if (eq && eq < amp) {
            size_t key_len = (size_t)(eq - key_start);
            size_t val_len = (size_t)(amp - (eq + 1));
            decode(key_start, key_len, main_key);
            decode(eq + 1,   val_len, main_val);
        } else {
            size_t key_len = (size_t)(amp - key_start);
            decode(key_start, key_len, main_key);
            main_val[0] = '\0';
        }
        printf("%s=%s\n", main_key, main_val);
        if (*amp == '&')
            p = amp + 1;
        else
            break;
    }
    return 0;
}
